package com.euvcraft.lithmod.mc.gametest;
import static com.euvcraft.lithmod.mc.gametest.T4RuntimeFixtures.*;
import com.euvcraft.lithmod.core.*;import com.euvcraft.lithmod.mc.*;import com.euvcraft.lithmod.mc.registry.*;import com.euvcraft.lithmod.mc.multiblock.advanced.*;import com.euvcraft.lithmod.mc.multiblock.scanner.*;import com.euvcraft.lithmod.mc.multiblock.utilities.*;import com.euvcraft.lithmod.mc.multiblock.assembly.*;
import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.gametest.framework.*;import net.minecraft.resources.*;import net.minecraft.server.level.*;import net.minecraft.server.network.CommonListenerCookie;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.item.*;import net.minecraft.world.level.material.Fluids;
import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.event.RegisterGameTestsEvent;import net.neoforged.neoforge.registries.DeferredRegister;import net.neoforged.neoforge.capabilities.Capabilities;import net.neoforged.neoforge.transfer.ResourceHandler;import net.neoforged.neoforge.transfer.fluid.FluidResource;import net.neoforged.neoforge.transfer.transaction.Transaction;
import com.mojang.authlib.GameProfile;import java.util.*;import java.util.function.Consumer;
public final class T5GameTests{
 private static final DeferredRegister<Consumer<GameTestHelper>> FUNCTIONS=DeferredRegister.create(Registries.TEST_FUNCTION,"lithmod");private static final Map<String,Consumer<GameTestHelper>> CASES=new LinkedHashMap<>();
 static{add("t5_utility_formation",T5GameTests::utilityFormation);add("t5_utility_transactions",T5GameTests::utilityTransactions);add("t5_utility_processing_reload",T5GameTests::utilityProcessing);add("t5_diagnostic_authority_paper",T5GameTests::diagnosticAuthority);add("t5_diagnostic_reload_hardware",T5GameTests::diagnosticReload);add("t5_fluid_pause_resume",T5GameTests::waterPause);add("t5_ultrapure_arcforge_pipe",T5GameTests::pipe);add("t5_chain_logic",h->chain(h,DieTypes.LOGIC));add("t5_chain_memory",h->chain(h,DieTypes.MEMORY));add("t5_chain_compute",h->chain(h,DieTypes.COMPUTE));add("t5_chain_nand",h->chain(h,DieTypes.NAND));add("t5_assembly_exact_counts",T5GameTests::assembly);add("t5_assembly_pause_reload",T5GameTests::assemblyPause);add("t5_high_binning_t4_t5",T5GameTests::binning);}
 private static void add(String id,Consumer<GameTestHelper> run){CASES.put(id,run);FUNCTIONS.register(id,()->run);}
 public static void register(IEventBus bus){FUNCTIONS.register(bus);bus.addListener((Consumer<RegisterGameTestsEvent>)event->{Holder<TestEnvironmentDefinition<?>> env=event.registerEnvironment(Identifier.parse("lithmod:t5_runtime"),new TestEnvironmentDefinition[0]);var data=new TestData<>(env,Level.OVERWORLD,Identifier.withDefaultNamespace("empty"),400,0,true,Rotation.NONE,false,1,1,false,0);for(var name:CASES.keySet()){var id=Identifier.fromNamespaceAndPath("lithmod",name);event.registerTest(id,new FunctionGameTestInstance(ResourceKey.<Consumer<GameTestHelper>>create(Registries.TEST_FUNCTION,id),data));}});}
 private static Cell small(GameTestHelper h,boolean utility,Direction facing,int column){int depth=utility?3:2,rx=switch(facing){case NORTH->1;case SOUTH->-1;default->0;},rz=switch(facing){case EAST->1;case WEST->-1;default->0;},bx=switch(facing){case EAST->-1;case WEST->1;default->0;},bz=switch(facing){case NORTH->1;case SOUTH->-1;default->0;};var anchor=h.absolutePos(new BlockPos(8+(rx<0?1:0)+(bx<0?depth-1:0)+rx*column,1,1+(rz<0?1:0)+(bz<0?depth-1:0)+rz*column));var positions=new ArrayList<BlockPos>();var level=h.getLevel();for(int u=0;u<2;u++)for(int v=0;v<2;v++)for(int d=0;d<depth;d++){var pos=anchor.offset(rx*(u-column)+bx*d,v,rz*(u-column)+bz*d);positions.add(pos);level.setBlock(pos,AdvancedMachines.ADVANCED_CASING.get().defaultBlockState(),3);}var spare=positions.stream().filter(x->!x.equals(anchor)).toList();level.setBlock(spare.get(0),AdvancedMachines.ADVANCED_POWER_PORT.get().defaultBlockState(),3);if(utility){level.setBlock(spare.get(1),UtilityMachines.WATER_INLET.get().defaultBlockState(),3);level.setBlock(spare.get(2),UtilityMachines.PURE_OUTLET.get().defaultBlockState(),3);}level.setBlock(anchor,(utility?UtilityMachines.CONTROLLER.get():AssemblyMachines.CONTROLLER.get()).defaultBlockState().setValue(AdvancedVisualProperties.FACING,facing),3);var machine=(com.euvcraft.lithmod.mc.machine.FabMachineBlockEntity)level.getBlockEntity(anchor);((AdvancedOwner)machine).revalidate();check(h,((AdvancedOwner)machine).isFormed(),"Small machine forms "+utility+facing+column);return new Cell(level,positions,anchor,machine);}
 private static BlockPos block(Cell c,Block b){return c.positions().stream().filter(p->c.level().getBlockState(p).getBlock()==b).findFirst().orElseThrow();}
 private static Cell scanner(GameTestHelper h){var c=build(h,Kind.SCANNER);var level=c.level();level.setBlock(block(c,ScannerMachines.OPTICS_MODULE.get()),ScannerMachines.IMMERSION_MODULE.get().defaultBlockState(),3);var free=c.positions().stream().filter(p->p.getY()==c.anchor().getY()+1&&level.getBlockState(p).getBlock()==AdvancedMachines.ADVANCED_CASING.get()).toList();level.setBlock(free.get(0),ScannerMachines.DIAGNOSTIC_PANEL.get().defaultBlockState(),3);level.setBlock(free.get(1),ScannerMachines.WATER_INLET.get().defaultBlockState(),3);var s=(ScannerControllerBlockEntity)c.machine();s.revalidate();check(h,s.isFormed()&&s.immersion(),"Immersion kit forms");return c;}
 private static ServerPlayer player(GameTestHelper h,BlockPos pos){var cookie=CommonListenerCookie.createInitial(new GameProfile(UUID.randomUUID(),"t5-test"),false);var p=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),cookie.gameProfile(),cookie.clientInformation());p.setPos(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5);return p;}
 private static void diagnose(GameTestHelper h,Cell c,int quality){var s=(ScannerControllerBlockEntity)c.machine();var pos=block(c,ScannerMachines.DIAGNOSTIC_PANEL.get());var p=player(h,pos);var menu=new DiagnosticMenu(4,p.getInventory(),s,pos);p.containerMenu=menu;var f=s.diagnostic();s.diagnosticPaper.setItem(0,new ItemStack(ModItems.BURN_PAPER.get(),2));check(h,menu.clickMenuButton(p,f.targetA()+200)&&menu.clickMenuButton(p,f.targetB()+601)&&menu.clickMenuButton(p,f.targetC()+(100-quality)*4+1002),"Coefficient entries accepted");check(h,menu.clickMenuButton(p,2000)&&menu.clickMenuButton(p,2001),"Paper plot then accept");eq(h,quality,s.diagnosticQuality(),"Diagnostic quality");eq(h,1,s.diagnosticPaper.getItem(0).getCount(),"Exactly one paper spent");p.containerMenu=p.inventoryMenu;}
 private static ResourceHandler<FluidResource> fluid(Cell c,Block block){var handler=c.level().getCapability(Capabilities.Fluid.BLOCK,block(c,block),Direction.UP);if(handler==null)throw new IllegalStateException("Fluid capability missing");return handler;}
 private static int insert(ResourceHandler<FluidResource> handler,FluidResource fluid,int amount,boolean commit){try(var tx=Transaction.openRoot()){int n=handler.insert(0,fluid,amount,tx);if(commit)tx.commit();return n;}}
 private static void utilityFormation(GameTestHelper h){for(var f:Direction.Plane.HORIZONTAL)for(int col=0;col<2;col++)try(var c=small(h,true,f,col)){eq(h,12,c.positions().size(),"12 members");var owner=(UtilityControllerBlockEntity)c.machine();for(var p:c.positions())check(h,(c.level().getCapability(Capabilities.Energy.BLOCK,p,null)!=null)==p.equals(c.port()),"Energy only power port");c.level().setBlock(block(c,UtilityMachines.PURE_OUTLET.get()),Blocks.AIR.defaultBlockState(),3);owner.revalidate();check(h,!owner.isFormed(),"Missing outlet unforms");}h.succeed();}
 private static void utilityTransactions(GameTestHelper h){try(var c=small(h,true,Direction.NORTH,0)){var s=(UtilityControllerBlockEntity)c.machine();var raw=fluid(c,UtilityMachines.WATER_INLET.get());var pure=fluid(c,UtilityMachines.PURE_OUTLET.get());var water=FluidResource.of(Fluids.WATER);var upw=FluidResource.of(UtilityFluids.ULTRAPURE_WATER.get());eq(h,1000,insert(raw,water,1000,false),"Simulation/abort accepts");eq(h,0,s.raw.amount(),"Abort rolls back");eq(h,0,insert(raw,upw,1000,true),"Raw inlet rejects UPW");eq(h,1000,insert(raw,water,1000,true),"Raw input committed");eq(h,0,insert(pure,upw,1000,true),"Output rejects insertion");s.pure.fill(900,false);try(var tx=Transaction.openRoot()){eq(h,300,pure.extract(0,upw,300,tx),"Extract journal");}eq(h,900,s.pure.amount(),"Extraction abort restores");try(var tx=Transaction.openRoot()){eq(h,300,pure.extract(0,upw,300,tx),"Extract actual");tx.commit();}eq(h,600,s.pure.amount(),"Exact source debit");c.level().setBlock(block(c,UtilityMachines.WATER_INLET.get()),Blocks.AIR.defaultBlockState(),3);eq(h,0,insert(raw,water,1000,true),"Retained lens refuses removed port");}h.succeed();}
 private static void utilityProcessing(GameTestHelper h){try(var c=small(h,true,Direction.NORTH,0)){var s=(UtilityControllerBlockEntity)c.machine();s.setSlot(0,new ItemStack(ModItems.UTILITY_FILTER.get(),2));s.setSlot(1,new ItemStack(Items.WATER_BUCKET));s.serverTick();eq(h,1000,s.raw.amount(),"Bucket fills exact water");check(h,s.slot(2).is(Items.BUCKET),"Bucket returned");insert(fluid(c,UtilityMachines.WATER_INLET.get()),FluidResource.of(Fluids.WATER),7000,true);replenish(s);s.serverTick();check(h,s.hasJob(),"Utility starts");eq(h,0,s.raw.amount(),"Batch water reserved once");eq(h,1,s.slot(0).getCount(),"Filter consumed once");s.setStoredEnergy(0);int progress=s.progress();s.serverTick();eq(h,progress,s.progress(),"No-power pause");var tag=save(c.level(),s);c.level().removeBlockEntity(c.anchor());s=new UtilityControllerBlockEntity(c.anchor(),c.level().getBlockState(c.anchor()));c.level().setBlockEntity(s);load(c.level(),s,tag);for(int i=0;i<1000&&s.pure.amount()==0;i++){replenish(s);s.serverTick();}eq(h,8000,s.pure.amount(),"Reload finishes exact pinned fluid");eq(h,1,s.slot(0).getCount(),"No second filter charge");}h.succeed();}
 private static void diagnosticAuthority(GameTestHelper h){try(var c=scanner(h)){var s=(ScannerControllerBlockEntity)c.machine();var pos=block(c,ScannerMachines.DIAGNOSTIC_PANEL.get());var p=player(h,pos);var menu=new DiagnosticMenu(7,p.getInventory(),s,pos);p.containerMenu=menu;check(h,!menu.clickMenuButton(p,2001),"Cannot accept without a paid plot");var before=s.diagnostic();check(h,!menu.clickMenuButton(p,2000)&&before.equals(s.diagnostic()),"No paper no plot");check(h,!menu.clickMenuButton(p,-1)&&!menu.clickMenuButton(p,1203),"Bad packets rejected");s.diagnosticPaper.setItem(0,new ItemStack(ModItems.BURN_PAPER.get(),3));p.containerMenu=p.inventoryMenu;check(h,!menu.clickMenuButton(p,2000),"Closed menu denied");p.containerMenu=menu;p.setPos(pos.getX()+20,pos.getY(),pos.getZ());check(h,!menu.clickMenuButton(p,2000),"Distance denied");eq(h,3,s.diagnosticPaper.getItem(0).getCount(),"Rejected attempts spend nothing");diagnose(h,c,100);check(h,s.diagnosed(),"Fit accepted");eq(h,37,menu.slots.size(),"Paper plus player inventory only");}h.succeed();}
 private static void diagnosticReload(GameTestHelper h){try(var c=scanner(h)){var s=(ScannerControllerBlockEntity)c.machine();ScannerGameTests.align(h,c,100);diagnose(h,c,100);var tag=save(c.level(),s);var fit=s.diagnostic();c.level().removeBlockEntity(c.anchor());s=new ScannerControllerBlockEntity(c.anchor(),c.level().getBlockState(c.anchor()));c.level().setBlockEntity(s);load(c.level(),s,tag);s.revalidate();check(h,s.diagnosed()&&s.calibrated()&&fit.equals(s.diagnostic()),"Both calibrations survive owner reload");var pos=block(c,ScannerMachines.IMMERSION_MODULE.get());c.level().setBlock(pos,Blocks.AIR.defaultBlockState(),3);c.level().setBlock(pos,ScannerMachines.IMMERSION_MODULE.get().defaultBlockState(),3);s.revalidate();check(h,!s.diagnosed()&&!s.calibrated(),"New module identity invalidates both");}h.succeed();}
 private static void inputs(ScannerControllerBlockEntity s,String family){var f=fresh(3,WaferSubstrate.PURE);f.set(ModDataComponents.FOUP_CONTENTS.get(),FoupItems.trustedContentsOf(f).withPreparationGeneration(2));s.setSlot(0,f);var m=new ItemStack(ModItems.MASK.get());m.set(ModDataComponents.MASK_DATA.get(),new MaskData(family,5,5,2));s.setSlot(1,m);s.setSlot(2,new ItemStack(ModItems.RESIST_T5.get(),64));}
 private static void waterPause(GameTestHelper h){try(var c=scanner(h)){var s=(ScannerControllerBlockEntity)c.machine();ScannerGameTests.align(h,c,100);diagnose(h,c,100);inputs(s,DieTypes.LOGIC);replenish(s);s.serverTick();check(h,!s.inputsLocked(),"No water denies admission");var input=fluid(c,ScannerMachines.WATER_INLET.get());eq(h,0,insert(input,FluidResource.of(Fluids.WATER),1000,true),"Ordinary water rejected by scanner");insert(input,FluidResource.of(UtilityFluids.ULTRAPURE_WATER.get()),2,true);s.serverTick();check(h,s.inputsLocked(),"Supplied calibrated T5 starts");s.serverTick();int p=s.progressTicks(),fe=s.buffer().getAmountAsInt();s.serverTick();eq(h,p,s.progressTicks(),"Water shortage pauses");eq(h,fe,s.buffer().getAmountAsInt(),"No FE wasted without water");insert(input,FluidResource.of(UtilityFluids.ULTRAPURE_WATER.get()),1000,true);s.serverTick();check(h,s.progressTicks()>p,"Water supply resumes");eq(h,998,s.pureWater.amount(),"Exact water per paid progress tick");}h.succeed();}
 private static void pipe(GameTestHelper h){try(var c=scanner(h)){var s=(ScannerControllerBlockEntity)c.machine();var inlet=block(c,ScannerMachines.WATER_INLET.get());var pipePos=inlet.above().above();var bridge=inlet.above();var tankPos=pipePos.above();var pipe=BuiltInRegistries.BLOCK.getValue(Identifier.parse("arcforge:wrought_fluid_conduit"));var tank=BuiltInRegistries.BLOCK.getValue(Identifier.parse("arcforge:wrought_fluid_tank"));var original=c.level().getBlockState(bridge);c.level().setBlock(bridge,ScannerMachines.WATER_INLET.get().defaultBlockState(),3);c.level().setBlock(inlet,AdvancedMachines.ADVANCED_CASING.get().defaultBlockState(),3);s.revalidate(); // Move inlet to upper frame: freely placed service port.
  c.level().setBlock(pipePos,pipe.defaultBlockState(),3);c.level().setBlock(tankPos,tank.defaultBlockState(),3);try{var be=(net.zagdrath.arcforge.blockentity.conduit.ConduitBlockEntity)c.level().getBlockEntity(pipePos);for(var side:Direction.values())be.setSetting(side,net.zagdrath.arcforge.conduit.SideSetting.DISABLED);be.setSetting(Direction.UP,net.zagdrath.arcforge.conduit.SideSetting.OUTPUT);be.setSetting(Direction.DOWN,net.zagdrath.arcforge.conduit.SideSetting.INPUT);net.zagdrath.arcforge.block.conduit.ConduitBlock.refreshConnections(c.level(),pipePos);var source=c.level().getCapability(Capabilities.Fluid.BLOCK,tankPos,Direction.UP);int supplied=0;for(int i=0;i<20&&supplied<1000;i++)supplied+=insert(source,FluidResource.of(UtilityFluids.ULTRAPURE_WATER.get()),1000-supplied,true);eq(h,1000,supplied,"Actual Arcforge tank accepts UPW");var manager=net.zagdrath.arcforge.conduit.network.ConduitNetworkManager.get(c.level());manager.markDirty(pipePos);for(int i=0;i<100;i++)manager.tick();eq(h,1000,s.pureWater.amount(),"Actual Arcforge pipes deliver custom fluid");eq(h,0,source.getAmountAsInt(0),"Source debited");}finally{c.level().setBlock(tankPos,Blocks.AIR.defaultBlockState(),3);c.level().setBlock(pipePos,Blocks.AIR.defaultBlockState(),3);c.level().setBlock(bridge,original,3);}
 }h.succeed();}
 private static void chain(GameTestHelper h,String family){ItemStack completed;try(var c=scanner(h)){var s=(ScannerControllerBlockEntity)c.machine();ScannerGameTests.align(h,c,80);diagnose(h,c,80);inputs(s,family);insert(fluid(c,ScannerMachines.WATER_INLET.get()),FluidResource.of(UtilityFluids.ULTRAPURE_WATER.get()),16000,true);for(int i=0;i<10000&&s.processState()!=ProcessState.FINISHED;i++){replenish(s);s.serverTick();}check(h,s.processState()==ProcessState.FINISHED,"T5 "+family+" completes");var lot=FoupItems.trustedContentsOf(s.slot(0));check(h,Math.abs(lot.run().effectiveYield()-.93*.9*.9)<1e-8,"Beam and diagnostic factors applied once");eq(h,8400,16000-s.pureWater.amount(),"42x100 paid ticks each2mB");eq(h,4,s.slot(1).get(ModDataComponents.MASK_DATA.get()).usesRemaining(),"One mask use");completed=s.slot(0).copy();s.clearSlot(0);}try(var c=build(h,Kind.PACKAGING)){var machine=(AdvancedTestPackageControllerBlockEntity)c.machine();machine.setSlot(0,completed);machine.setSlot(1,new ItemStack(ModItems.CHIP_PACKAGE.get(),64));var product=packageAll(h,machine,ChipCatalog.chipFor(family,5).orElseThrow(),3);eq(h,3,product.chips()+product.scrap(),"Exactly one judgment per wafer");}h.succeed();}
 private static void assembly(GameTestHelper h){try(var c=small(h,false,Direction.NORTH,0)){var s=(AssemblyControllerBlockEntity)c.machine();for(var row:List.of(new Item[]{ModItems.COMPUTE_CHIP_T3.get(),ModItems.CPU_BLANK.get(),ModItems.CPU_T3.get()},new Item[]{ModItems.MEMORY_CHIP_T5.get(),ModItems.DIMM_BLANK.get(),ModItems.DIMM_T5.get()},new Item[]{ModItems.LOGIC_CHIP_T1.get(),ModItems.MICROCONTROLLER_BLANK.get(),ModItems.MICROCONTROLLER_T1.get()})){int chips=row[2]==ModItems.DIMM_T5.get()?4:1;s.setSlot(0,new ItemStack(row[0],chips));s.setSlot(1,new ItemStack(row[1]));for(int i=0;i<1000&&s.outputSlot().isEmpty();i++){replenish(s);s.serverTick();}check(h,s.outputSlot().is(row[2]),"Same-tier assembly result");eq(h,1,s.outputSlot().getCount(),"One assembly");check(h,s.slot(0).isEmpty()&&s.slot(1).isEmpty(),"Exact chip and blank counts consumed");s.clearSlot(2);}s.setSlot(0,new ItemStack(ModItems.MEMORY_CHIP_T5.get(),3));s.setSlot(1,new ItemStack(ModItems.DIMM_BLANK.get()));for(int i=0;i<400;i++){replenish(s);s.serverTick();}check(h,s.outputSlot().isEmpty()&&s.slot(0).getCount()==3,"Three memory chips cannot make DIMM");}h.succeed();}
 private static void assemblyPause(GameTestHelper h){for(var f:Direction.Plane.HORIZONTAL)for(int col=0;col<2;col++)try(var c=small(h,false,f,col)){var s=(AssemblyControllerBlockEntity)c.machine();s.setSlot(0,new ItemStack(ModItems.LOGIC_CHIP_T2.get()));s.setSlot(1,new ItemStack(ModItems.MICROCONTROLLER_BLANK.get()));replenish(s);for(int i=0;i<10;i++)s.serverTick();int progress=s.data().get(2);s.setStoredEnergy(0);for(int i=0;i<5;i++)s.serverTick();eq(h,progress,s.data().get(2),"Assembly pauses without FE");var tag=save(c.level(),s);c.level().removeBlockEntity(c.anchor());s=new AssemblyControllerBlockEntity(c.anchor(),c.level().getBlockState(c.anchor()));c.level().setBlockEntity(s);load(c.level(),s,tag);for(int i=0;i<400&&s.outputSlot().isEmpty();i++){replenish(s);s.serverTick();}check(h,s.outputSlot().is(ModItems.MICROCONTROLLER_T2.get()),"Assembly resumes after reload");eq(h,1,s.outputSlot().getCount(),"No duplicate after reload");}h.succeed();}
 private static void binning(GameTestHelper h){for(String family:List.of(DieTypes.LOGIC,DieTypes.COMPUTE))try(var c=build(h,Kind.PACKAGING)){var s=(AdvancedTestPackageControllerBlockEntity)c.machine();check(h,s.toggleHighBinning(),"Enable binning");s.setSlot(0,complete(4,family,1));s.setSlot(1,new ItemStack(ModItems.CHIP_PACKAGE.get(),64));var result=packageAll(h,s,ChipCatalog.chipFor(family,5).orElseThrow(),3);eq(h,3,result.chips()+result.scrap(),"T4 high-bin outputs T5 or scrap");}h.succeed();}
 private T5GameTests(){}
}

